mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.DB_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.DB_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.ASSET_ID,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.DB_ID = #{dbId}
AND T1.DB_NAME = #{dbName}
AND T1.ASSET_ID = #{assetId}
AND T1.SYSTEM_ID = #{systemId}
AND T1.ENGINE_CD = #{engineCd}
AND T1.STATUS_CD = #{statusCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.DB_ID AS DB_ID, T1.DB_NAME AS DB_NAME, T1.ENGINE_CD AS ENGINE_CD, T1.VERSION_NO AS VERSION_NO, T1.ASSET_ID AS ASSET_ID, T1.SYSTEM_ID AS SYSTEM_ID, T1.EOL_DATE AS EOL_DATE, T1.STATUS_CD AS STATUS_CD, T1.REMARK AS REMARK, T1.REG_USER_ID AS REG_USER_ID, T1.REG_DTM AS REG_DTM, T1.CHG_USER_ID AS CHG_USER_ID, T1.CHG_DTM AS CHG_DTM
      FROM TB_IF_DB_INSTANCE_PILOT T1

     ORDER BY T1.REG_DTM DESC, T1.DB_ID ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}
